let strongholdControlsSnapshot=null,strongholdControlsLoading=null,strongholdControlsBusy=false,strongholdControlsLoadedAt=0,strongholdControlsMessage='';
function shcEscape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function strongholdControlsHTML(snapshot,ownAllianceName=''){
 const alliances=snapshot.alliances||[],claims=snapshot.claims||[],name=id=>alliances.find(a=>a.id===id)?.name||id,own=alliances.find(a=>a.name===ownAllianceName),managed=new Set(alliances.filter(a=>a.canManage).map(a=>a.id));
 const visible=claims.filter(c=>c.status!=='released'&&(c.allianceId===own?.id||managed.has(c.allianceId)||managed.has(c.transferTarget)||snapshot.canAdjudicate&&c.status==='disputed'));
 const rows=visible.map(c=>{const editable=managed.has(c.allianceId),empty=Number(c.assetCount)===0,available=c.status==='active'||c.status==='inactive',targets=alliances.filter(a=>a.id!==c.allianceId),accept=available&&empty&&managed.has(c.transferTarget);
 return '<article class="shc-claim"><div class="shc-heading"><h4>'+shcEscape(name(c.allianceId))+'</h4><span class="tag">'+shcEscape(c.status)+'</span></div><dl><dt>Reserved galaxy</dt><dd>'+shcEscape(c.galaxy)+'</dd><dt>Structures / reservations</dt><dd>'+shcEscape(c.assetCount||0)+'</dd></dl>'+(c.transferTarget?'<p>Transfer offered to <b>'+shcEscape(name(c.transferTarget))+'</b>.</p>':'')+(!empty?'<p class="note">Existing structures or build reservations must be removed before release or transfer. Asset ownership is never moved automatically.</p>':'')+(editable&&available?'<div class="controls"><button type="button" class="btn" data-shc-action="release" data-shc-claim="'+shcEscape(c.id)+'" '+(empty?'':'disabled')+'>RELEASE RESERVATION</button></div>'+(targets.length?'<form data-shc-form="offerTransfer" data-shc-claim="'+shcEscape(c.id)+'"><label>Transfer to alliance<select name="targetAllianceId" required '+(empty?'':'disabled')+'>'+targets.map(a=>'<option value="'+shcEscape(a.id)+'">'+shcEscape(a.name)+'</option>').join('')+'</select></label><button class="btn" '+(empty?'':'disabled')+'>OFFER TRANSFER</button></form>':''):'')+(accept?'<button type="button" class="btn primary" data-shc-action="transfer" data-shc-claim="'+shcEscape(c.id)+'" data-shc-target="'+shcEscape(c.transferTarget)+'">ACCEPT TRANSFER</button>':'')+(c.status==='disputed'?'<p class="note">Disputed reservation: new claims, construction and disputed bonuses remain blocked pending staff resolution.</p>':'')+'</article>';
 }).join('');
 const disputed=claims.filter(c=>c.status==='disputed');
 const adjudication=snapshot.canAdjudicate&&disputed.length?'<details class="shc-adjudication"><summary>STAFF · RESOLVE DISPUTED RESERVATION</summary><form data-shc-form="resolve"><label>Winning claim<select name="winnerClaimId" required>'+disputed.map(c=>'<option value="'+shcEscape(c.id)+'">'+shcEscape(name(c.allianceId))+' · '+shcEscape(c.galaxy)+'</option>').join('')+'</select></label><label>Resulting status<select name="winnerStatus"><option value="active">Active</option><option value="inactive">Inactive · reservation retained</option></select></label><label>Audit reason<textarea name="reason" rows="3" maxlength="2000" required></textarea></label><p>Resolution preserves occupied assets. The server rejects a choice that would discard another claim’s assets.</p><button class="btn">RESOLVE CONFLICT</button></form></details>':'';
 return '<section class="panel shc-panel"><div class="ph"><div class="pt">STRONGHOLD RESERVATIONS</div><button type="button" class="btn" data-shc-refresh>REFRESH</button></div><div class="shc-body"><p class="shc-status" role="status">'+shcEscape(strongholdControlsMessage)+'</p><p>Residence does not grant ownership. An inactive claim keeps its reservation until explicitly released.</p><div class="shc-grid">'+(rows||'<p>No stronghold reservation or transfer offer for your alliance.</p>')+'</div>'+adjudication+'</div></section>';
}
async function shcRequest(body){const response=await fetch('/api/strongholds',{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});let data;try{data=await response.json();}catch{throw new Error('The server returned an unreadable stronghold response.');}if(!response.ok)throw new Error(data.error||'Stronghold request failed.');return data;}
async function renderStrongholdControls(force=false){const root=document.getElementById('strongholdControls');if(!root)return;if(force||!strongholdControlsSnapshot||Date.now()-strongholdControlsLoadedAt>15000){if(!strongholdControlsLoading){strongholdControlsLoading=shcRequest().then(data=>{strongholdControlsSnapshot=data;strongholdControlsLoadedAt=Date.now();}).finally(()=>{strongholdControlsLoading=null;});}try{await strongholdControlsLoading;}catch(error){root.textContent=error.message;return;}}if(root.isConnected!==false)root.innerHTML=strongholdControlsHTML(strongholdControlsSnapshot,typeof state==='undefined'?'':state.alliance?.name||'');if(strongholdControlsBusy)root.querySelectorAll('button,select,textarea').forEach(el=>el.disabled=true);}
async function submitStrongholdControl(action,fields){if(strongholdControlsBusy||!strongholdControlsSnapshot)return;strongholdControlsBusy=true;strongholdControlsMessage='Saving…';await renderStrongholdControls();let outcome;try{await shcRequest({...fields,action,generation:strongholdControlsSnapshot.generation,revision:strongholdControlsSnapshot.revision,operationId:'shc-'+crypto.randomUUID()});outcome='Stronghold reservation updated.';}catch(error){outcome=error.message;}finally{strongholdControlsBusy=false;strongholdControlsMessage=outcome;await renderStrongholdControls(true);}}
document.addEventListener('click',event=>{if(event.target.closest('[data-staff-tab="alliances"]'))renderStrongholdControls();const refresh=event.target.closest('[data-shc-refresh]');if(refresh){strongholdControlsMessage='';renderStrongholdControls(true);return;}const button=event.target.closest('[data-shc-action]');if(!button||button.disabled)return;const action=button.dataset.shcAction;if(!confirm(action==='release'?'Release this empty stronghold reservation?':'Accept this stronghold transfer?'))return;submitStrongholdControl(action,{claimId:button.dataset.shcClaim,...(button.dataset.shcTarget?{targetAllianceId:button.dataset.shcTarget}:{})});});
document.addEventListener('submit',event=>{const form=event.target.closest('[data-shc-form]');if(!form)return;event.preventDefault();if(strongholdControlsBusy)return;const values=Object.fromEntries(new FormData(form)),action=form.dataset.shcForm;if(action==='resolve'){values.reason=String(values.reason||'').trim();if(!values.reason){strongholdControlsMessage='An audit reason is required.';renderStrongholdControls();return;}values.staffOverride=true;}if(form.dataset.shcClaim)values.claimId=form.dataset.shcClaim;if(!confirm(action==='resolve'?'Resolve this disputed reservation with the selected winner?':'Offer this empty reservation to the selected alliance?'))return;submitStrongholdControl(action,values);});
